// Regenerates the client's two generated files from the repo's sources of truth (run from client/: bun run gen):
//   src/abi.ts     the ABI subsets the client calls, from the wall's generated ABIs (wall/packages/market/src/abi.ts,
//                  wall/packages/report/src/abi.ts, wall/packages/market/src/kuru-abi.ts), every error kept so a
//                  revert decodes to its name
//   src/static.ts  the Monad testnet deployments (contracts/deployments/10143.json and 10143-indexes.json) and the
//                  launch panel of the six GPUs (wall/packages/sources/panels/launch.json): slot order, family names,
//                  the reserve
// test/static.test.ts fails when either file drifts from its sources.
import { join } from "node:path";

const ROOT = join(import.meta.dir, "..", "..");

export const PICK = {
  agateDollarAbi: { from: "market", name: "agateDollarAbi", fns: ["balanceOf", "allowance", "approve", "drip", "nextDripAt", "dripAmount", "dripPeriod", "decimals", "symbol", "name", "totalSupply"], events: ["Dripped", "Transfer", "Approval"] },
  agateTokenAbi: { from: "market", name: "agateTokenAbi", fns: ["balanceOf", "allowance", "approve", "totalSupply", "name", "symbol", "decimals", "series"], events: ["Transfer", "Approval"] },
  agateSeriesAbi: { from: "market", name: "agateSeriesAbi", fns: "*", events: "*" },
  agateFactoryAbi: { from: "market", name: "agateFactoryAbi", fns: ["currentMonth", "seriesOf", "marketOf", "isSeries", "routerCanUse", "gpuIds", "labelOf", "previewListing", "index", "dollar", "router", "kuruRouter", "tag", "takerFeeBps", "makerFeeBps"], events: ["SeriesListed", "MarketRecorded"] },
  agateRouterAbi: { from: "market", name: "agateRouterAbi", fns: "*", events: "*" },
  agateIndexAbi: { from: "report", name: "agateIndexAbi", fns: ["record", "head", "gpu", "slotState", "slotStates", "slotWindow", "familyOf", "readings", "clocks", "dayStart", "dayId", "firstRecordDay", "finalFix", "writers", "attester", "disrupted"], events: ["DayClosed", "Attested", "DayCarried"] },
} as const;

type Entry = { type: string; name?: string };

function pick(abi: readonly Entry[], fns: readonly string[] | "*", events: readonly string[] | "*"): Entry[] {
  return abi.filter((e) => {
    if (e.type === "error") return true;
    if (e.type === "function") return fns === "*" || fns.includes(e.name!);
    if (e.type === "event") return events === "*" || events.includes(e.name!);
    return false;
  });
}

export async function renderAbi(): Promise<string> {
  const market = (await import(join(ROOT, "wall/packages/market/src/abi.ts"))) as Record<string, readonly Entry[]>;
  const report = (await import(join(ROOT, "wall/packages/report/src/abi.ts"))) as Record<string, readonly Entry[]>;
  const kuru = (await import(join(ROOT, "wall/packages/market/src/kuru-abi.ts"))) as Record<string, readonly Entry[]>;
  let body =
    "// GENERATED by scripts/gen-static.ts from the wall's generated ABIs (wall/packages/market/src/abi.ts, kuru-abi.ts,\n" +
    "// wall/packages/report/src/abi.ts): the functions and events the client calls, and every error. Do not edit.\n";
  for (const [exportName, p] of Object.entries(PICK)) {
    const src = p.from === "market" ? market : report;
    const abi = src[p.name];
    if (!abi) throw new Error(`no ${p.name} in the ${p.from} ABIs`);
    body += `export const ${exportName} = ${JSON.stringify(pick(abi, p.fns, p.events))} as const;\n`;
  }
  for (const k of ["kuruOrderBookAbi", "kuruMarginAccountAbi"]) {
    body += `export const ${k} = ${JSON.stringify(kuru[k])} as const;\n`;
  }
  return body;
}

interface Panel {
  gpu: string;
  spec: string;
  gpuId: string;
  families: { name: string; famQ: number }[];
  slots: { slot: number; sourceId: string; family: number; liveAtStart: boolean }[];
}

export async function renderStatic(): Promise<string> {
  const dep = await Bun.file(join(ROOT, "contracts/deployments/10143.json")).json();
  const idx = await Bun.file(join(ROOT, "contracts/deployments/10143-indexes.json")).json();
  const launch = (await Bun.file(join(ROOT, "wall/packages/sources/panels/launch.json")).json()) as { panels: Panel[]; deploy: { gpu: string; gpuId: string; spec: string; family: number[]; liveAtStartMask: number }[] };
  const panels = launch.deploy.map((d) => {
    const p = launch.panels.find((x) => x.gpu === d.gpu);
    if (!p) throw new Error(`launch.json has no panel for ${d.gpu}`);
    if (p.gpuId.toLowerCase() !== d.gpuId.toLowerCase()) throw new Error(`${d.gpu}: the panel's gpuId is not the deploy entry's`);
    if (p.slots.length !== d.family.length) throw new Error(`${d.gpu}: the panel's slots are not the deploy entry's`);
    return {
      gpu: d.gpu,
      gpuId: d.gpuId.toLowerCase(),
      spec: d.spec,
      slots: p.slots.map((s) => ({ slot: s.slot, family: p.families[s.family]!.name, sourceId: s.sourceId, liveAtStart: s.liveAtStart })),
    };
  });
  const indexes: Record<string, { index: string; firstDay: number; deployBlock: number }> = {};
  for (const k of ["production", "demo"]) {
    const r = idx[k];
    if (r && r.status === "deployed") indexes[k] = { index: r.index, firstDay: r.firstDay, deployBlock: r.deployBlock };
  }
  return (
    "// GENERATED by scripts/gen-static.ts from contracts/deployments/10143.json, 10143-indexes.json and\n" +
    "// wall/packages/sources/panels/launch.json. Do not edit.\n" +
    'import type { Deployments, PanelGpu } from "./types.ts";\n\n' +
    "/** contracts/deployments/10143.json: the market on Monad testnet. */\n" +
    `export const TESTNET_DEPLOYMENTS: Deployments = ${JSON.stringify(dep, null, 2)};\n\n` +
    "/** contracts/deployments/10143-indexes.json: each deployed index, its first day and deploy block. */\n" +
    `export const TESTNET_INDEXES: Record<string, { index: string; firstDay: number; deployBlock: number }> = ${JSON.stringify(indexes, null, 2)};\n\n` +
    "/** The launch panel (wall/packages/sources/panels/launch.json): per GPU its slots in index order, each slot's\n" +
    " *  cloud family and whether it was live at the start (false: the reserve). */\n" +
    `export const PANELS: PanelGpu[] = ${JSON.stringify(panels, null, 2)};\n`
  );
}

if (import.meta.main) {
  await Bun.write(join(import.meta.dir, "../src/abi.ts"), await renderAbi());
  await Bun.write(join(import.meta.dir, "../src/static.ts"), await renderStatic());
  console.log("wrote src/abi.ts and src/static.ts");
}
